/**
 * Authoritative Invoice PDF Printing Helper
 *
 * Prints the exact canonical PDF generated by @react-pdf/renderer
 * instead of relying on browser HTML printing.
 */
export async function printInvoicePdf(pdfUrl: string): Promise<void> {
  const res = await fetch(pdfUrl, { cache: "no-store" });
  if (!res.ok) {
    let msg = "Failed to load invoice PDF for printing";
    try {
      const data = await res.json();
      if (data?.error) msg = data.error;
    } catch {
      /* ignore */
    }
    throw new Error(msg);
  }

  const blob = await res.blob();
  const blobUrl = URL.createObjectURL(blob);

  // Hidden iframe to invoke print on the PDF directly
  const iframe = document.createElement("iframe");
  iframe.style.position = "fixed";
  iframe.style.right = "0";
  iframe.style.bottom = "0";
  iframe.style.width = "0";
  iframe.style.height = "0";
  iframe.style.border = "0";
  iframe.src = blobUrl;
  document.body.appendChild(iframe);

  return new Promise((resolve, reject) => {
    iframe.onload = () => {
      try {
        iframe.contentWindow?.focus();
        iframe.contentWindow?.print();
        resolve();
      } catch (err) {
        // Fallback for browsers that restrict iframe.print()
        const win = window.open(blobUrl, "_blank");
        if (win) {
          win.focus();
          resolve();
        } else {
          reject(err);
        }
      } finally {
        setTimeout(() => {
          iframe.remove();
          URL.revokeObjectURL(blobUrl);
        }, 60000);
      }
    };

    iframe.onerror = (e) => {
      iframe.remove();
      URL.revokeObjectURL(blobUrl);
      reject(new Error("Failed to load PDF iframe"));
    };
  });
}
